105	function escapeHtml(text: string): string {
106	  const map: { [key: string]: string } = {
107	    '&': '&amp;',
108	    '<': '&lt;',
109	    '>': '&gt;',
110	    '"': '&quot;',
111	    "'": '&#039;'
112	  };
113	  return text.replace(/[&<>"']/g, char => map[char]);
114	}
