8	export function parseFrontmatter(content: string): { data: Frontmatter; content: string } {
9	  const lines = content.split('\n');
10	
11	  if (!lines[0].startsWith('---')) {
12	    return { data: {}, content };
13	  }
14	
15	  let endIndex = -1;
16	  for (let i = 1; i < lines.length; i++) {
17	    if (lines[i].startsWith('---')) {
18	      endIndex = i;
19	      break;
20	    }
21	  }
22	
23	  if (endIndex === -1) {
24	    return { data: {}, content };
25	  }
26	
27	  const frontmatterBlock = lines.slice(1, endIndex).join('\n');
28	  const markdownContent = lines.slice(endIndex + 1).join('\n');
29	
30	  const data = parseYAML(frontmatterBlock);
31	
32	  return { data, content: markdownContent };
33	}
34	
35	function parseYAML(yamlStr: string): Frontmatter {
36	  const data: Frontmatter = {};
37	
38	  if (!yamlStr.trim()) {
39	    return data;
40	  }
41	
42	  const lines = yamlStr.split('\n');
43	  for (const line of lines) {
44	    if (!line.trim() || line.trim().startsWith('#')) {
45	      continue;
46	    }
47	
48	    const colonIndex = line.indexOf(':');
49	    if (colonIndex === -1) {
50	      continue;
51	    }
52	
53	    const key = line.substring(0, colonIndex).trim();
54	    let value = line.substring(colonIndex + 1).trim();
55	
56	    if (value.startsWith('"') && value.endsWith('"')) {
57	      value = value.slice(1, -1);
58	    } else if (value.startsWith("'") && value.endsWith("'")) {
59	      value = value.slice(1, -1);
60	    } else if (value === 'true') {
61	      data[key] = true;
62	      continue;
63	    } else if (value === 'false') {
64	      data[key] = false;
65	      continue;
66	    } else if (value.startsWith('[') && value.endsWith(']')) {
67	      const arrayStr = value.slice(1, -1);
68	      data[key] = arrayStr.split(',').map(item => item.trim());
69	      continue;
70	    }
71	
72	    data[key] = value;
73	  }
74	
75	  return data;
76	}
